values ('npc_general_merchant', 'General Merchant', 'Supplies Dealer', 'MERCHANT', 'NEUTRAL', 'Nexus Crossroads', 'NEXUS_CROSSROADS', 'A stout, weathered trader who has operated from the same stall in Nexus Core for over two decades. His worn ledger holds debts from half the district.', 'gruff_but_fair', 'Credits talk, everything else walks. What do you need?', 'shop_general_01', 'dialog_merchant_greet', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop"]'::jsonb, 0)
