values ('npc_master_blacksmith', 'Master Blacksmith', 'Forge Master', 'CRAFTER', 'NONE', 'Nexus Core Forge Quarter', 'NEXUS_CORE', 'A veteran smith who has equipped three generations of Concordium soldiers. His hands are more scar than skin.', 'no_nonsense', 'Steel doesn''t care about feelings. Bring materials and coin, I''ll do the rest.', 'shop_materials_01', 'dialog_blacksmith_greet', NULL, NULL, NULL, NULL, NULL, '["CRAFT", "BUY", "SELL"]'::jsonb, '["open_upgrade"]'::jsonb, 1)
