values ('npc_innkeeper', 'Innkeeper', 'Rest & Recuperation', 'INNKEEPER', 'NONE', 'Nexus Core Commons', 'NEXUS_CORE', 'A cheerful matron who runs the only reputable lodging in the district. She knows everyone''s business and tells no one.', 'warm_informative', 'Rest your feet, friend. Rooms are clean, food''s hot, and I''ve heard it all — so save the excuses.', NULL, 'dialog_innkeeper_greet', NULL, NULL, NULL, NULL, NULL, '["REST", "INFO", "RUMOR"]'::jsonb, '["rest_inn"]'::jsonb, 2)
