values ('npc_quest_board', 'Bounty & Quest Board', 'Automated Terminal', 'TERMINAL', 'NONE', 'Nexus Core Central Hall', 'NEXUS_CORE', 'An automated posting terminal that aggregates Concordium-approved contracts and public bounties.', 'automated', '[TERMINAL ACTIVE] Select contract category to proceed.', NULL, 'dialog_quest_terminal', NULL, NULL, NULL, NULL, NULL, '["QUEST_LIST", "BOUNTY_LIST"]'::jsonb, '[]'::jsonb, 3)
