values ('npc_freelance_bounty_board', 'Freelance Bounty Board', 'Black Market Terminal', 'TERMINAL', 'NONE', 'Nexus Core Outer Ring', 'NEXUS_CORE', 'A battered board covered in handwritten flyers, unofficial contracts, and the occasional wanted poster. No Concordium oversight here.', 'automated', '[BOARD] Unstamped listings. No guarantees. Payment on delivery.', NULL, 'dialog_bounty_terminal', NULL, NULL, NULL, NULL, NULL, '["BOUNTY_LIST", "FREELANCE_CONTRACTS"]'::jsonb, '[]'::jsonb, 4)
