values ('npc_concordium_officer', 'Officer Valen', 'Nexus Security', 'QUEST_GIVER', 'CONCORDIUM', 'Nexus Core Command Post', 'NEXUS_CORE', 'An efficient Concordium field officer who processes security contracts and inter-faction liaison requests. His medals are real; his patience is not.', 'disciplined_formal', 'Identification. Purpose. Proceed.', NULL, 'dialog_valen_main', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 5)
