values ('npc_director_hale', 'Director Hale', 'Concordium Administrator', 'QUEST_GIVER', 'CONCORDIUM', 'Inner Cradle Exclusion Zone Command', 'INNER_CRADLE_EXCLUSION', 'Director Hale oversees Concordium containment operations in the Inner Cradle. Cold and calculating, she treats casualties as acceptable variables.', 'calculating_authoritative', 'Every asset is expendable if the mission succeeds. I''ll be direct with you.', NULL, 'dialog_hale_main', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 6)
