values ('npc_concordium_overseer', 'Overseer Vael', 'Logistics Command', 'INFO', 'CONCORDIUM', 'Cradle Outer Ring Checkpoint', 'CRADLE_OUTER_RING', 'A bureaucrat stationed at the outer boundary, cataloguing anomalous energy readings with obsessive precision.', 'anxious_detailed', 'The readings are off again. Don''t touch anything without filing a request.', NULL, 'dialog_vael_main', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 7)
