values ('npc_garden_scout', 'Scout Rian', 'Recon Unit', 'INFO', 'CONCORDIUM', 'Aethel Gardens Patrol Route', 'AETHEL_GARDENS', 'A young Concordium scout on rotation through the Gardens, cataloguing flora mutations and monster migration patterns.', 'curious_cautious', 'Eyes open out here — the mutations near the eastern cluster have been getting aggressive.', NULL, 'dialog_rian_scout', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 8)
