values ('npc_scavenger', 'Junk-Eye Joe', 'Scavenger', 'MERCHANT', 'NONE', 'Broken Civil Quarter Debris Field', 'BROKEN_CIVIL_QUARTER', 'Junk-Eye Joe lost one eye to a collapsing ceiling in this very district. He replaced it with a salvaged scope lens and kept digging.', 'eccentric_resourceful', 'Junk? Treasure? Same thing, different buyer. Let''s talk.', 'shop_scrap_01', 'dialog_scavenger', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop"]'::jsonb, 9)
