values ('npc_veteran_explorer', 'Old Man Kael', 'Veteran Explorer', 'QUEST_GIVER', 'CONCORDIUM', 'Broken Civil Quarter Ruins', 'BROKEN_CIVIL_QUARTER', 'Old Man Kael claims to have explored every district before the Great Fracture. His stories contradict each other perfectly.', 'eccentric_knowledgeable', 'Sit down. This''ll take a minute. Or don''t — your loss.', NULL, 'dialog_veteran_kael', NULL, NULL, NULL, NULL, NULL, '["QUEST", "INFO"]'::jsonb, '[]'::jsonb, 11)
