values ('npc_blacksmith_ironhand', 'Ironhand', 'Elite Forgemaster', 'CRAFTER', 'IRON_HEGEMONY', 'Bastion Core Forge District', 'BASTION_CORE', 'Ironhand earned his name when his right arm was replaced with a hydraulic exo-limb after a forge accident. Best thing that ever happened to his craft.', 'proud_skilled', 'Hegemony steel or something you''ve dragged in from the wasteland. Either way, I can work with it.', 'shop_blacksmith_02', 'dialog_ironhand', NULL, NULL, NULL, NULL, NULL, '["CRAFT", "BUY", "SELL"]'::jsonb, '["open_upgrade"]'::jsonb, 19)
