values ('npc_scrap_merchant', 'Rusty', 'Scrap Dealer', 'MERCHANT', 'NONE', 'Scrap Field Market', 'SCRAP_FIELD', 'Rusty runs the most chaotic stall in the Scrap Field, selling things he definitely did not assemble himself and definitely works.', 'shady_cheerful', 'Certified pre-owned! That''s my official position and I''m sticking to it.', 'shop_scrap_02', 'dialog_rusty', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop"]'::jsonb, 20)
