values ('npc_iron_miner', 'Gorn', 'Shift Foreman', 'INFO', 'IRON_HEGEMONY', 'Iron Ravine Mine Entrance', 'IRON_RAVINE', 'Gorn has mined the Ravine since before the Hegemony claimed it. He works for them now but misses the silence.', 'stoic_reluctant', 'Ores go down, iron comes up, credits change hands. That''s all there is.', NULL, 'dialog_gorn_miner', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 21)
