values ('npc_salvage_expert', 'Tink', 'Salvage Expert', 'MERCHANT', 'IRON_HEGEMONY', 'Titan Assembly Yard', 'TITAN_ASSEMBLY_YARD', 'Tink specialises in extracting usable components from decommissioned Hegemony war machines. Her shop smells of coolant and ambition.', 'technical_enthusiastic', 'Every busted machine has one good thing left in it. I find it. You buy it. Works for everyone.', 'shop_tech_01', 'dialog_salvage_tink', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop"]'::jsonb, 22)
