values ('npc_assembly_foreman', 'Foreman Brigg', 'Titan Assembly', 'QUEST_GIVER', 'IRON_HEGEMONY', 'Titan Assembly Yard Command Post', 'TITAN_ASSEMBLY_YARD', 'Foreman Brigg coordinates construction of Hegemony heavy units. He dispatches anyone who slows the line.', 'driven_impatient', 'Clock''s running. Make it worth my time.', NULL, 'dialog_brigg_foreman', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 23)
