values ('npc_cartel_boss', 'Don Vercelli', 'Cartel Underboss', 'QUEST_GIVER', 'MERIDIAN_CARTEL', 'Port Meridian Cartel Headquarters', 'PORT_MERIDIAN', 'Don Vercelli controls the Port Meridian dockside trade with a smile that never quite reaches his eyes. Everyone owes him something.', 'charming_dangerous', 'Welcome, welcome! Sit down. Have you eaten? Everyone eats at my table before we talk business.', NULL, 'dialog_vercelli_boss', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 24)
