values ('npc_wetland_fisher', 'Old Salty', 'Fisherman', 'INFO', 'NONE', 'Coral Wetlands Fishing Platform', 'CORAL_WETLANDS', 'Old Salty has fished the Wetlands for fifty years and has opinions on everything. He shares them whether asked or not.', 'talkative_weathered', 'Careful out past the orange markers — something big has been circling.', NULL, 'dialog_salty_fisher', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 25)
