values ('npc_shady_smuggler', 'Sly', 'Smuggler', 'MERCHANT', 'MERIDIAN_CARTEL', 'Smuggler Jungle Hidden Camp', 'SMUGGLER_JUNGLE', 'Sly operates out of a camp so well hidden that even Cartel enforcers can''t find it consistently. His prices reflect the inconvenience.', 'paranoid_professional', 'You''re either a customer or a problem. Which is it?', 'shop_blackmarket_01', 'dialog_sly_smuggler', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop"]'::jsonb, 26)
