values ('npc_black_market_dealer', 'Madam Z', 'Contraband Dealer', 'MERCHANT', 'MERIDIAN_CARTEL', 'Black Dock Market Underground', 'BLACK_DOCK_MARKET', 'Madam Z runs the most sophisticated black-market operation in three sectors. Her network spans factions. Her records are encrypted to oblivion.', 'elegant_ruthless', 'Everything has a price. The question is what you''re willing to offer.', 'shop_blackmarket_02', 'dialog_madam_z', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop"]'::jsonb, 27)
