values ('npc_ruin_diver', 'Kip', 'Deep Diver', 'QUEST_GIVER', 'MERIDIAN_CARTEL', 'Sunken Aethel Ruin Dockside', 'SUNKEN_AETHEL_RUIN', 'Kip free-dives the submerged Aethel ruins for Cartel clients, recovering artifacts that pre-date the current age. She has drowned three times and keeps going.', 'reckless_driven', 'Got three contracts open and a window before the tide shifts. Short version: I need backup.', NULL, 'dialog_kip_diver', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 28)
