values ('npc_omnicorp_executive', 'Director Sterling', 'OmniCorp Executive', 'QUEST_GIVER', 'OMNICORP', 'The Spire Executive Floor', 'THE_SPIRE', 'Director Sterling manages OmniCorp field operations with corporate detachment. He sees people as human capital.', 'corporate_cold', 'Your efficiency rating is under evaluation. Perform accordingly.', NULL, 'dialog_sterling_exec', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 29)
