values ('npc_omnicorp_technician', 'Tech Officer 404', 'Systems Analyst', 'QUEST_GIVER', 'OMNICORP', 'Skybridge Reactor Control Room', 'SKYBRIDGE_REACTOR', 'Tech Officer 404 handles everything from hardware diagnostics to covert extraction — and prefers not to explain why the two are related.', 'terse_precise', 'Task assigned. Completion expected. Questions are inefficient.', NULL, 'dialog_tech404_side', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 30)
