values ('npc_plateau_surveyor', 'Surveyor Unit 7', 'Automated Drone', 'INFO', 'OMNICORP', 'Highland Plateau Survey Station', 'HIGHLAND_PLATEAU', 'Surveyor Unit 7 is an autonomous OmniCorp drone with a remarkable personality subroutine that it has never been permitted to act on.', 'politely_constrained', 'Surveyor Unit 7 online. Please state your resource-extraction inquiry.', NULL, 'dialog_drone_7', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 31)
