values ('npc_extraction_chief', 'Chief Barrett', 'Extraction Operations', 'QUEST_GIVER', 'OMNICORP', 'Extraction Zone Delta Command', 'EXTRACTION_ZONE_DELTA', 'Chief Barrett has run OmniCorp extraction sites for eighteen years. She is equal parts miner, geologist, and combat veteran.', 'practical_commanding', 'We''re behind quota. If you''re here to help, I''ll be grateful. If not, get clear of the machinery.', NULL, 'dialog_barrett_chief', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 32)
