values ('npc_grid_security', 'Warden AI', 'Security Grid', 'TERMINAL', 'OMNICORP', 'Secure Mining Grid Checkpoint', 'SECURE_MINING_GRID', 'Warden AI manages access to OmniCorp''s most sensitive mining operations. It has never once bent a rule.', 'logical_immovable', '[WARDEN-7] Clearance verification required. Unauthorised access terminates this session.', NULL, 'dialog_warden_ai', NULL, NULL, NULL, NULL, NULL, '["INFO", "QUEST"]'::jsonb, '[]'::jsonb, 33)
