values ('npc_reactor_engineer', 'Engineer Cross', 'Core Maintainer', 'INFO', 'OMNICORP', 'Skybridge Reactor Maintenance Bay', 'SKYBRIDGE_REACTOR', 'Engineer Cross keeps the Skybridge Reactor from melting down on a daily basis. He has not taken a day off in three years.', 'stressed_brilliant', 'I have exactly four minutes before the coolant flush. Talk fast.', NULL, 'dialog_cross_engineer', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 34)
