values ('npc_high_priest', 'High Priestess Lyr', 'Voice of the Shard', 'QUEST_GIVER', 'CHILDREN_OF_THE_SHARD', 'Sanctum Inner Chamber', 'SANCTUM', 'High Priestess Lyr is the spiritual and operational leader of the Children of the Shard. She speaks in certainties because she has heard the Shard speak.', 'serene_absolute', 'The Shard has already seen this meeting. Come — what you seek to ask, it already knows.', NULL, 'dialog_lyr_main', NULL, NULL, NULL, NULL, NULL, '["QUEST", "INFO"]'::jsonb, '[]'::jsonb, 35)
