values ('npc_acolyte_mera', 'Acolyte Mera', 'Forest Guide', 'QUEST_GIVER', 'CHILDREN_OF_THE_SHARD', 'Sanctum Outer Courtyard', 'SANCTUM', 'Acolyte Mera is the High Priestess'' deputy and does most of the work that keeping a religious order running actually requires.', 'pragmatic_faithful', 'Lyr handles the visions. I handle the schedules. What can I help you with?', NULL, 'dialog_mera_side', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 36)
