values ('npc_forest_acolyte', 'Brother Silas', 'Acolyte', 'INNKEEPER', 'CHILDREN_OF_THE_SHARD', 'Glowvine Forest Ritual Path', 'GLOWVINE_FOREST', 'Brother Silas tends the sacred Glowvine paths, pruning the luminescent vines and guiding pilgrims through the forest''s more disorienting sections.', 'gentle_contemplative', 'Walk slowly here. The Glowvines respond to rushed energy.', NULL, 'dialog_silas_forest', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '["rest_inn"]'::jsonb, 37)
