values ('npc_swamp_hermit', 'The Hermit', 'Outcast', 'MERCHANT', 'NONE', 'Shardroot Swamp Edge', 'SHARDROOT_SWAMP', 'The Hermit lives alone at the swamp''s edge and claims the isolation is his by choice. His knowledge of Shard-touched flora is unmatched.', 'cryptic_wise', 'The swamp provides. Coin helps too. What are you after?', 'shop_hermit_01', 'dialog_hermit', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL", "INFO"]'::jsonb, '["open_shop"]'::jsonb, 38)
