values ('npc_shrine_keeper', 'Keeper Norn', 'Shrine Guardian', 'QUEST_GIVER', 'CHILDREN_OF_THE_SHARD', 'Fragment Shrine', 'FRAGMENT_SHRINE', 'Keeper Norn has maintained the Fragment Shrine for three generations of her family. The shrine remembers what history has tried to erase.', 'devoted_historical', 'Leave an offering, or don''t — the Shard judges intent, not tribute.', NULL, 'dialog_norn_keeper', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 39)
