values ('npc_drill_sergeant_korg', 'Sergeant Korg', 'Drill Master', 'QUEST_GIVER', 'STARFORGED_LEGION', 'Fortress Kaelen Training Grounds', 'FORTRESS_KAELEN', 'Sergeant Korg has broken and rebuilt more recruits than any drill sergeant in Legion history. He considers this a compliment.', 'loud_demanding', 'WHAT ARE YOU DOING STANDING THERE. Move, recruit!', NULL, 'dialog_korg_side', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 42)
