values ('npc_dune_scout', 'Scout Jace', 'Forward Recon', 'INFO', 'STARFORGED_LEGION', 'Dune Outskirts Watchtower', 'DUNE_OUTSKIRTS', 'Scout Jace runs the farthest perimeter patrols alone and prefers it that way. She knows the dunes better than the sand knows itself.', 'independent_sharp', 'Sandstorm coming from the west in three hours. You''ll want to be clear of the flats.', NULL, 'dialog_jace_scout', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 43)
