values ('npc_lost_blacksmith', 'Smithy Dan', 'Lost Blacksmith', 'CRAFTER', 'NONE', 'Cradle Expanse Forge Camp', 'CRADLE_EXPANSE', 'Smithy Dan set up a forge in the middle of nowhere after being blacklisted by every guild. His work is better than his manners.', 'bitter_talented', 'Took the long route to find me. Good — means you actually need something forged right.', 'shop_materials_02', 'dialog_dan_smithy', NULL, NULL, NULL, NULL, NULL, '["CRAFT", "BUY", "SELL"]'::jsonb, '["open_upgrade"]'::jsonb, 46)
