values ('npc_battlefield_medic', 'Medic Vance', 'Combat Medic', 'INNKEEPER', 'NONE', 'Border Skirmish Ring Field Station', 'BORDER_SKIRMISH_RING', 'Medic Vance works the neutral zone, patching up anyone from any faction. He says he has no politics. Everyone believes him.', 'neutral_matter_of_fact', 'Wound first, introductions second. Sit down.', 'shop_medic_01', 'dialog_vance_medic', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop", "rest_inn"]'::jsonb, 47)
