values ('npc_reckless_scout', 'Scout Jax', 'Storm Chaser', 'INFO', 'NONE', 'Cradle Expanse Deep Zone', 'CRADLE_EXPANSE', 'Scout Jax goes where no briefing covers and comes back with information no intel team was willing to get.', 'reckless_confident', 'I''ve been to the dead zones. Twice. Still alive, so clearly I''m doing something right.', NULL, 'dialog_jax_scout', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 49)
