values ('npc_doomsayer', 'The Prophet', 'Doomsayer', 'INFO', 'NONE', 'Shattered Heart', 'SHATTERED_HEART', 'The Prophet claims to have seen how every faction ends. His predictions are specific, detailed, and have a troubling accuracy rate.', 'dramatic_accurate', 'I see you''ve come to hear something terrible. I''ll oblige.', NULL, 'dialog_prophet', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 52)
on conflict (npc_id) do update set name=excluded.name, title=excluded.title, role=excluded.role, faction=excluded.faction, location=excluded.location, region_id=excluded.region_id, description=excluded.description, personality=excluded.personality, greeting=excluded.greeting, shop_inventory=excluded.shop_inventory, dialogue_tree=excluded.dialogue_tree, buy_currency=excluded.buy_currency, rest_currency=excluded.rest_currency, sell_note=excluded.sell_note, quest_category=excluded.quest_category, reward_currency=excluded.reward_currency, available_services=excluded.available_services, actions=excluded.actions, sort_order=excluded.sort_order;
insert into public.npcs (npc_id, name, title, role, faction, location, region_id, description, personality, greeting, shop_inventory, dialogue_tree, buy_currency, rest_currency, sell_note, quest_category, reward_currency, available_services, actions, sort_order)
values ('npc_core_technician', 'Tech Lead Aris', 'Siphon Control', 'QUEST_GIVER', 'CONCORDIUM', 'Aethel Siphon Core', 'AETHEL_SIPHON_CORE', 'Tech Lead Aris maintains the most dangerous energy extraction operation in the Concordium — a job that has taken three predecessors.', 'focused_haunted', 'The Core is stable. For now. I need someone who can run interference on the eastern conduit.', NULL, 'dialog_aris_core', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 53)
on conflict (npc_id) do update set name=excluded.name, title=excluded.title, role=excluded.role, faction=excluded.faction, location=excluded.location, region_id=excluded.region_id, description=excluded.description, personality=excluded.personality, greeting=excluded.greeting, shop_inventory=excluded.shop_inventory, dialogue_tree=excluded.dialogue_tree, buy_currency=excluded.buy_currency, rest_currency=excluded.rest_currency, sell_note=excluded.sell_note, quest_category=excluded.quest_category, reward_currency=excluded.reward_currency, available_services=excluded.available_services, actions=excluded.actions, sort_order=excluded.sort_order;
