values ('npc_master_kael', 'Master Kael', 'Legendary Forgesmith', 'CRAFTER', 'NONE', 'Prima Materia Forge', 'PRIMA_MATERIA_FORGE', 'Master Kael is the only living crafter authorised to work with Prima Materia. He accepts commissions once per season, if he finds the requester worthy.', 'exacting_legendary', 'Most people who come here aren''t ready. Convince me you''re different.', 'shop_master_kael', 'dialog_master_kael', NULL, NULL, NULL, NULL, NULL, '["CRAFT"]'::jsonb, '["open_upgrade"]'::jsonb, 54)
