values ('npc_ancient_ghost', 'Echo of Aethelgard', 'Lost Spirit', 'INFO', 'NONE', 'Hidden Aethelgardian City', 'HIDDEN_AETHELGARDIAN_CITY', 'The Echo of Aethelgard is a residual consciousness from before the Fracture, preserved in a crystalline matrix. Its memories are the only record of the old world.', 'melancholic_vast', 'You stand in what was once a great city. I am what remembers it.', NULL, 'dialog_ancient_ghost', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 56)
