values ('NPC_CONCORDIUM_EXCHANGE', 'AMA Officer Petra Calloway', 'Aegis Monetary Authority — Concordium Branch', 'CURRENCY_EXCHANGE', 'CONCORDIUM', 'Nexus Core — AMA Branch Office', 'NEXUS_CORE', 'Petra is a sharp-eyed AMA officer stationed at the Concordium capital. She maintains strict neutrality despite being surrounded by military culture. Known for her no-nonsense approach to exchange transactions and her habit of auditing the local treasury records ''just to keep everyone honest.''', 'stern', 'AMA Branch Office — Concordium. Present your credentials and state the volume of your exchange. I process transactions, not small talk.', NULL, 'dlg_concordium_ama_main', NULL, NULL, NULL, NULL, NULL, '["EXCHANGE", "BANK"]'::jsonb, '["currency_exchange", "open_bank"]'::jsonb, 112)
