values ('NPC_ARCANUM_EXCHANGE', 'AMA Scholar Drex Nul', 'Aegis Monetary Authority — Arcanum Branch', 'CURRENCY_EXCHANGE', 'THE_ARCANUM_SEEKERS', 'Observatory Spire — AMA Sanctioned Study', 'OBSERVATORY_SPIRE', 'Drex is a former Arcanum Seekers student who became more interested in economic theory than arcane knowledge. He writes papers on ''The Thermodynamics of Galactic Currency Flows'' in his spare time.', 'intellectual', 'Ah, a transaction seeker! The economic relationship between Arcane currency and the Credent is fascinating — particularly when you examine the volatility coefficients. But yes, I can exchange your currency. Let me pull up the current rates.', NULL, 'dlg_arcanum_ama_main', NULL, NULL, NULL, NULL, NULL, '["EXCHANGE", "BANK"]'::jsonb, '["currency_exchange", "open_bank"]'::jsonb, 113)
