values ('NPC_IRON_EXCHANGE', 'AMA Terminal IH-3', 'Aegis Monetary Authority — Iron Hegemony Automated Terminal', 'CURRENCY_EXCHANGE', 'IRON_HEGEMONY', 'Bastion Core — AMA Processing Center', 'BASTION_CORE', 'The Iron Hegemony preferred efficiency over personality, so they lobbied for an automated AMA terminal. IH-3 processes transactions with industrial efficiency and has no patience for errors.', 'mechanical', 'TERMINAL IH-3 ACTIVE. INSERT CURRENCY VOLUME. EXCHANGE RATE DISPLAYED. CONFIRM OR ABORT. PROCESSING FEE APPLIES.', NULL, 'dlg_iron_ama_main', NULL, NULL, NULL, NULL, NULL, '["EXCHANGE", "BANK"]'::jsonb, '["currency_exchange", "open_bank"]'::jsonb, 114)
