values ('NPC_MERIDIAN_EXCHANGE', 'AMA Broker Sable Thorn', 'Aegis Monetary Authority — Meridian Branch', 'CURRENCY_EXCHANGE', 'MERIDIAN_CARTEL', 'Port Meridian — AMA Trade Desk', 'PORT_MERIDIAN', 'Sable Thorn navigated from Cartel trader to AMA broker with calculated grace. The Meridian branch is the busiest in Xylos by transaction volume. She occasionally tips clients about exchange rate trends.', 'charming', 'Welcome, welcome! You''ve come to the right desk — the Meridian AMA branch handles more volume than all other branches combined. What are we converting today?', NULL, 'dlg_meridian_ama_main', NULL, NULL, NULL, NULL, NULL, '["EXCHANGE", "BANK"]'::jsonb, '["currency_exchange", "open_bank"]'::jsonb, 115)
