values ('NPC_OMNICORP_EXCHANGE', 'AMA Node OM-7', 'Aegis Monetary Authority — OmniCorp Integration', 'CURRENCY_EXCHANGE', 'OMNICORP', 'The Spire — AMA Digital Hub', 'THE_SPIRE', 'OmniCorp integrated the AMA terminal directly into their corporate network infrastructure. OM-7 is technically an AMA node but runs on OmniCorp servers. The AMA audits this arrangement quarterly.', 'corporate', 'OmniCorp AMA Integration Node — powered by OmniCorp CoreNet™. Your exchange request has been submitted to the AMA Ledger. Processing. Terms and conditions apply.', NULL, 'dlg_omnicorp_ama_main', NULL, NULL, NULL, NULL, NULL, '["EXCHANGE", "BANK"]'::jsonb, '["currency_exchange", "open_bank"]'::jsonb, 116)
