values ('NPC_SHARD_EXCHANGE', 'AMA Keeper Mirya of the Still Pool', 'Aegis Monetary Authority — Shard Branch', 'CURRENCY_EXCHANGE', 'CHILDREN_OF_THE_SHARD', 'Sanctum — AMA Sanctuary Desk', 'SANCTUM', 'Mirya bridges spiritual and financial worlds: a genuine Shard practitioner who also holds AMA certification. She meditates between transactions and occasionally warns clients about ''spiritually inauspicious exchange moments.''', 'serene', 'Breathe... the Shard sees all flows, including those of currency. I am Mirya. Let us proceed mindfully.', NULL, 'dlg_shard_ama_main', NULL, NULL, NULL, NULL, NULL, '["EXCHANGE", "BANK"]'::jsonb, '["currency_exchange", "open_bank"]'::jsonb, 117)
