values ('NPC_LEGION_EXCHANGE', 'AMA Agent Rex Valdur', 'Aegis Monetary Authority — Starforged Legion Post', 'CURRENCY_EXCHANGE', 'STARFORGED_LEGION', 'Fortress Kaelen — AMA Forward Station', 'FORTRESS_KAELEN', 'Rex is an AMA field agent who thrives in volatile frontier environments. He''s processed exchanges under fire, during bombardments, and once mid-warp. He respects the Legion''s boldness while maintaining AMA neutrality.', 'resilient', 'AMA Forward Station, Legion Post. Rex Valdur, at your service. Quick processing, fair rates — no extra charge for the excitement. What are we moving today?', NULL, 'dlg_legion_ama_main', NULL, NULL, NULL, NULL, NULL, '["EXCHANGE", "BANK"]'::jsonb, '["currency_exchange", "open_bank"]'::jsonb, 118)
