values ('NPC_NEXUS_MERCHANT_ELARA', 'Elara Voss', 'Supply Coordinator, Pax Nexus', 'MERCHANT', 'NEUTRAL', 'Pax Nexus — The Common Market', 'NEXUS_CORE', 'A former Meridian Cartel logistics officer who left after witnessing the human cost of trade wars. She now runs a supply stall in the Nexus, selling to anyone with enough CRD and a civil manner. Elara is known for her encyclopedic knowledge of contraband detection and her distaste for faction politics.', 'pragmatic', 'Welcome to Elara''s Supplies. I don''t care what flag you fly — just don''t cause trouble in my stall. What do you need?', 'shop_nexus_elara', 'dlg_nexus_elara_main', 'CRD', NULL, 'Sells potions, consumables, survival gear', NULL, NULL, '["BUY"]'::jsonb, '["open_shop"]'::jsonb, 126)
