values ('NPC_NEXUS_MERCHANT_GRATH', 'Grath ''Ironhide'' Rendall', 'Combat Outfitter', 'MERCHANT', 'NEUTRAL', 'Pax Nexus — The Armorer''s Alley', 'NEXUS_CORE', 'A retired Iron Hegemony sergeant with a cybernetic left arm and a grudge against every faction equally. He sells weapons, repair kits, and battle supplies. He claims to have fought in seven wars for five different factions before deciding none of them were worth dying for.', 'gruff', 'You look like you''ve been through a meat grinder. Or you''re about to be. Either way, I''ve got what you need. In CRD.', 'shop_nexus_grath', 'dlg_nexus_grath_main', 'CRD', NULL, 'Sells weapons, armor repair kits, combat tools', NULL, NULL, '["BUY"]'::jsonb, '["open_shop"]'::jsonb, 127)
