insert into public.npcs (npc_id, name, title, role, faction, location, region_id, description, personality, greeting, shop_inventory, dialogue_tree, buy_currency, rest_currency, sell_note, quest_category, reward_currency, available_services, actions, sort_order)
values ('NPC_NEXUS_INNKEEPER_TESSARA', 'Tessara of the Three Moons', 'Keeper of The Wanderer''s Rest', 'INNKEEPER', 'NEUTRAL', 'Pax Nexus — The Wanderer''s Rest', 'NEXUS_CORE', 'A former Arcanum Seekers adept who left the Order after discovering that true peace of mind doesn''t come from forbidden knowledge, but from a warm meal and a good night''s sleep. She operates the finest inn in the Nexus, famous for the restorative quality of her brews and her uncanny ability to read a person''s soul.', 'warm', 'Ah, a wanderer with tired eyes. Come, rest your burdens. My inn welcomes all who arrive in peace. Your body will thank you in the morning.', 'shop_nexus_tessara_brews', 'dlg_nexus_tessara_main', 'CRD', 'CRD', 'Rest restores full HP/MP of player + allies. Sells specialty recovery drinks.', NULL, NULL, '["REST", "BUY"]'::jsonb, '["rest_inn", "open_shop"]'::jsonb, 128)
