values ('NPC_NEXUS_BLACKSMITH_VULKAN', 'Vulkan Dross', 'Master Blacksmith of the Crucible', 'CRAFTER', 'NEUTRAL', 'Pax Nexus — The Crucible', 'NEXUS_CORE', 'Vulkan was once a legendary weapons master for the Starforged Legion before a catastrophic forge accident left him without faction allegiance or half his hearing. He rebuilt his workshop in the Nexus and now crafts for anyone. He has a unique skill: he can work with materials from ANY faction, which no capital blacksmith is willing to do.', 'meticulous', 'Materials on the bench, CRD in the slot. I don''t chit-chat while I work, but I''ll say this — what comes off my forge won''t disappoint you.', 'shop_nexus_vulkan', 'dlg_nexus_vulkan_main', 'CRD', NULL, 'Can craft using materials from any faction. Unlocks cross-faction recipes.', NULL, NULL, '["CRAFT", "BUY"]'::jsonb, '["open_crafting", "open_shop"]'::jsonb, 129)
