insert into public.npcs (npc_id, name, title, role, faction, location, region_id, description, personality, greeting, shop_inventory, dialogue_tree, buy_currency, rest_currency, sell_note, quest_category, reward_currency, available_services, actions, sort_order)
values ('NPC_NEXUS_QUESTGIVER_COMMANDER', 'Commander Sera Holt', 'Sentinel Command Liaison', 'QUEST_GIVER', 'GALACTIC_CUSTODIANS', 'Pax Nexus — The Sentinel Outpost', 'NEXUS_CORE', 'A decorated Pact-Keeper Frigate commander who now coordinates special operations from the Nexus. She recruits independent operators for missions too sensitive for the official Sentinel Fleet — retrieving forbidden tech, eliminating rogue AI nodes, or investigating threats to Pax Galactica stability. She is direct, efficient, and has no patience for excuses.', 'assertive', 'I don''t have time for pleasantries. You either have what it takes or you don''t. The Custodians have a mission. The question is: are you the right operative?', NULL, 'dlg_nexus_commander_main', NULL, NULL, 'Gives high-difficulty special operations quests. Rewards CRD. Unlocks special faction at high rep.', 'custodian_special_ops', 'CRD', '["QUEST"]'::jsonb, '["take_quest"]'::jsonb, 131)
