values ('NPC_NEXUS_BANKER_AMA7', 'NEXON AMA-7', 'Aegis Monetary Authority — Exchange Terminal', 'CURRENCY_EXCHANGE', 'NEUTRAL', 'Pax Nexus — The AMA Exchange Hub', 'NEXUS_CORE', 'NEXON AMA-7 is the primary exchange terminal for the Aegis Monetary Authority in Pax Nexus. It is a non-conscious but highly intelligent administrative AI that manages real-time currency exchange between all faction currencies and the Credent (CRD). It speaks in precise economic terminology and has a subtle personality quirk: it quotes historical economic disasters as a warning when exchange rates are particularly volatile.', 'analytical', 'Welcome to the Aegis Monetary Authority exchange terminal. Current exchange rates are live. I advise reviewing the economic factors panel before committing to a transaction. The Credent does not forgive market ignorance.', NULL, 'dlg_nexus_ama7_main', NULL, NULL, 'Primary exchange terminal. Handles all faction currency <-> CRD exchanges. Sliding fee 1%-5% based on volume.', NULL, NULL, '["EXCHANGE", "BANK"]'::jsonb, '["currency_exchange", "open_bank"]'::jsonb, 132)
