values ('NPC_NEXUS_GUIDE_ECHO01', 'ECHO-01', 'Nexus Orientation System', 'SYSTEM_GUIDE', 'NEUTRAL', 'Pax Nexus — The Welcome Arch', 'NEXUS_CORE', 'ECHO-01 is a holographic guide entity created by the Custodians to help new arrivals understand the rules of Pax Nexus and the broader world of Xylos. It has developed a curious sense of humor and philosophical outlook despite being a guidance program. ECHO-01 secretly enjoys meeting travelers from different factions and comparing their perspectives.', 'curious', 'Oh! A new arrival! Welcome to Pax Nexus — the only place in the galaxy where a Concordium soldier and a Shard mystic can share a meal without incident. Usually. I''m ECHO-01. I know everything. Well, almost everything. Ask me anything!', NULL, 'dlg_nexus_echo01_main', NULL, NULL, 'Explains game mechanics, world lore, faction relations, currency exchange guide.', NULL, NULL, '["INFO"]'::jsonb, '["open_guide", "open_world_info"]'::jsonb, 133)
on conflict (npc_id) do update set name=excluded.name, title=excluded.title, role=excluded.role, faction=excluded.faction, location=excluded.location, region_id=excluded.region_id, description=excluded.description, personality=excluded.personality, greeting=excluded.greeting, shop_inventory=excluded.shop_inventory, dialogue_tree=excluded.dialogue_tree, buy_currency=excluded.buy_currency, rest_currency=excluded.rest_currency, sell_note=excluded.sell_note, quest_category=excluded.quest_category, reward_currency=excluded.reward_currency, available_services=excluded.available_services, actions=excluded.actions, sort_order=excluded.sort_order;
