values ('NPC_NEXUS_INFO_CHRONICLER', 'The Chronicler', 'Keeper of the Galactic Archive', 'INFO', 'NEUTRAL', 'Pax Nexus — The Archive Spire', 'NEXUS_CORE', 'The Chronicler is an ancient being of unknown species who has been recording galactic history for longer than any faction has existed. It/they speak in a calm, layered voice that seems to come from multiple directions at once. The Chronicler offers history, lore, and cryptic hints about world events. Occasionally, it whispers of things that have not happened yet.', 'mysterious', 'Ah. Another thread arrives to be woven into the tapestry. I have recorded ten thousand such arrivals. Tell me, traveler — which version of yourself do you wish to become? I have seen all of them.', NULL, 'dlg_nexus_chronicler_main', NULL, NULL, 'Provides deep lore entries, faction histories, and rare discovery quests that unlock hidden regions.', 'lore_discovery', NULL, '["INFO", "QUEST"]'::jsonb, '["open_lore", "take_quest"]'::jsonb, 134)
on conflict (npc_id) do update set name=excluded.name, title=excluded.title, role=excluded.role, faction=excluded.faction, location=excluded.location, region_id=excluded.region_id, description=excluded.description, personality=excluded.personality, greeting=excluded.greeting, shop_inventory=excluded.shop_inventory, dialogue_tree=excluded.dialogue_tree, buy_currency=excluded.buy_currency, rest_currency=excluded.rest_currency, sell_note=excluded.sell_note, quest_category=excluded.quest_category, reward_currency=excluded.reward_currency, available_services=excluded.available_services, actions=excluded.actions, sort_order=excluded.sort_order;
