values ('NPC_NEXUS_DIPLOMAT_VAEL', 'Ambassador Vael Drosian', 'Custodian Ambassador at Large', 'QUEST_GIVER', 'GALACTIC_CUSTODIANS', 'Pax Nexus — The Diplomat''s Quarter', 'NEXUS_CORE', 'Ambassador Vael is the Custodians'' highest diplomatic representative in Pax Nexus. They navigate the razor-thin line between faction politics with grace, and occasionally task trusted operatives with missions that shape inter-faction relations. Completing Vael''s quests can shift faction war status, unlock peace treaties, or trigger major world events.', 'diplomatic', 'Peace is not the absence of conflict, traveler. It is the choice to act differently. I have a few... diplomatic errands that require someone who can operate beyond faction lines. Interested?', NULL, 'dlg_nexus_vael_main', NULL, NULL, 'Gives high-stakes diplomatic quests that affect world state (war/peace between factions). Very high CRD rewards.', 'diplomatic_special', 'CRD', '["QUEST"]'::jsonb, '["take_quest"]'::jsonb, 135)
on conflict (npc_id) do update set name=excluded.name, title=excluded.title, role=excluded.role, faction=excluded.faction, location=excluded.location, region_id=excluded.region_id, description=excluded.description, personality=excluded.personality, greeting=excluded.greeting, shop_inventory=excluded.shop_inventory, dialogue_tree=excluded.dialogue_tree, buy_currency=excluded.buy_currency, rest_currency=excluded.rest_currency, sell_note=excluded.sell_note, quest_category=excluded.quest_category, reward_currency=excluded.reward_currency, available_services=excluded.available_services, actions=excluded.actions, sort_order=excluded.sort_order;
