values ('NPC_NEXUS_HEALER_MIRA', 'Sister Mira Solari', 'Field Medic, Pax Nexus Infirmary', 'INNKEEPER', 'NEUTRAL', 'Pax Nexus — The Infirmary', 'NEXUS_CORE', 'Mira was once a battlefield medic for the Children of the Shard before her faith in their methods was shattered after a brutal campaign. She left the Shard with their medical knowledge intact and a vow to heal without discrimination. The Nexus Infirmary she runs is open to all factions, all hours. She is gentle, precise, and deeply empathetic.', 'compassionate', 'You''ve been hurt. I can see it — not just in your body. Come. The Infirmary is open to all. No politics, no faction marks, no judgments. Just healing.', 'shop_nexus_mira_medical', 'dlg_nexus_mira_main', 'CRD', 'CRD', 'Restores HP/MP of all party members. Sells advanced medical consumables. Slightly cheaper than Tessara but less ambiance.', NULL, NULL, '["REST", "BUY"]'::jsonb, '["rest_inn", "open_shop"]'::jsonb, 137)
