values ('NPC_NEXUS_TRAINER_AXIS', 'AXIS', 'Class Advancement Terminal — Pax Nexus', 'CLASS_TRAINER', 'NEUTRAL', 'Pax Nexus — The Training Matrix', 'NEXUS_CORE', 'AXIS is a holographic training AI that can facilitate class advancement for any faction''s character build. Unlike capital-based trainers who specialize only in their faction''s classes, AXIS can handle cross-faction hybrid advancement paths. This makes it the most sought-after trainer in Xylos, and the most expensive.', 'precise', 'AXIS Class Advancement Terminal online. I support all class trees from all seven factions, including cross-faction hybrid builds unavailable at capital trainers. Standard fee in CRD applies. Shall we begin assessment?', NULL, 'dlg_nexus_axis_main', 'CRD', NULL, 'Class advancement for any faction. Unique: can unlock cross-faction hybrid class paths.', NULL, NULL, '["CLASS_CHANGE"]'::jsonb, '["open_class_change"]'::jsonb, 139)
