values ('npc_ledger_warden_nexus_core', 'Seraph-7', 'Ledger Warden — Nexus Core', 'BANKER', 'GALACTIC_CUSTODIANS', 'Nexus Core', 'NEXUS_CORE', 'A Galactic Custodian field agent assigned to the financial sovereignty infrastructure of Nexus Core. Processes vault deposits, withdrawals, and AMA-regulated currency exchange under Pax Nexus protocol.', 'formal', 'Authorization confirmed. Vault and exchange services are available. What do you require, citizen?', NULL, 'dlg_custodian_banker', 'CRD', NULL, 'Neutral Custodian vault and currency exchange. No faction affiliation.', NULL, NULL, '["VAULT", "EXCHANGE"]'::jsonb, '["open_bank", "currency_exchange"]'::jsonb, 140)
