values ('npc_ledger_warden_observatory_spire', 'Lira-Sigma', 'Ledger Warden — Observatory Spire', 'BANKER', 'GALACTIC_CUSTODIANS', 'Observatory Spire', 'OBSERVATORY_SPIRE', 'Assigned to the Arcanum Seekers'' capital. Lira-Sigma maintains strict non-partisan financial services — vault and exchange are governed entirely by Custodian regulation, not Arcanum policy.', 'formal', 'Pax Nexus protocol active. Your assets are held under Custodian jurisdiction here — independent of Arcanum authority.', NULL, 'dlg_custodian_banker', 'CRD', NULL, 'Neutral Custodian vault and currency exchange. No faction affiliation.', NULL, NULL, '["VAULT", "EXCHANGE"]'::jsonb, '["open_bank", "currency_exchange"]'::jsonb, 141)
