values ('npc_ledger_warden_bastion_core', 'Vorath-9', 'Ledger Warden — Bastion Core', 'BANKER', 'GALACTIC_CUSTODIANS', 'Bastion Core', 'BASTION_CORE', 'Stationed within the Iron Hegemony''s fortified capital. Vorath-9 is the only entity in Bastion Core that answers to no commanding officer — only to the Custodian Charter.', 'formal', 'Custodian clearance active. No rank-based access exceptions here. State your financial requirement.', NULL, 'dlg_custodian_banker', 'CRD', NULL, 'Neutral Custodian vault and currency exchange. No faction affiliation.', NULL, NULL, '["VAULT", "EXCHANGE"]'::jsonb, '["open_bank", "currency_exchange"]'::jsonb, 142)
