insert into public.npcs (npc_id, name, title, role, faction, location, region_id, description, personality, greeting, shop_inventory, dialogue_tree, buy_currency, rest_currency, sell_note, quest_category, reward_currency, available_services, actions, sort_order)
values ('npc_ledger_warden_port_meridian', 'Nessa-Prime', 'Ledger Warden — Port Meridian', 'BANKER', 'GALACTIC_CUSTODIANS', 'Port Meridian', 'PORT_MERIDIAN', 'Port Meridian''s high trade volume makes Nessa-Prime one of the busiest Ledger Wardens in the sector. The Cartel''s market activity means this vault processes more exchange transactions per cycle than any other capital.', 'formal', 'Vault open, rates live. The Cartel''s currency moves fast — so do we. State your transaction.', NULL, 'dlg_custodian_banker', 'CRD', NULL, 'Neutral Custodian vault and currency exchange. No faction affiliation.', NULL, NULL, '["VAULT", "EXCHANGE"]'::jsonb, '["open_bank", "currency_exchange"]'::jsonb, 143)
