values ('npc_ledger_warden_the_spire', 'AXIS-4', 'Ledger Warden — The Spire', 'BANKER', 'GALACTIC_CUSTODIANS', 'The Spire', 'THE_SPIRE', 'Deployed at OmniCorp''s corporate capital. AXIS-4 operates with machine precision. OmniCorp attempted to renegotiate Custodian neutrality terms three times. All requests were denied.', 'formal', 'Transaction terminal online. OmniCorp has no jurisdiction over this node. Vault and exchange access confirmed.', NULL, 'dlg_custodian_banker', 'CRD', NULL, 'Neutral Custodian vault and currency exchange. No faction affiliation.', NULL, NULL, '["VAULT", "EXCHANGE"]'::jsonb, '["open_bank", "currency_exchange"]'::jsonb, 144)
