values ('npc_ledger_warden_sanctum', 'Verek-Null', 'Ledger Warden — Sanctum', 'BANKER', 'GALACTIC_CUSTODIANS', 'Sanctum', 'SANCTUM', 'The Children of the Shard accepted the Custodian presence in Sanctum reluctantly. Verek-Null serves without comment on Aethel doctrine — a silence the Shard interprets as neutrality, and the Custodians confirm it.', 'formal', 'Custodian Vault — active under Pax Nexus. The Aethel has no domain here. What do you require?', NULL, 'dlg_custodian_banker', 'CRD', NULL, 'Neutral Custodian vault and currency exchange. No faction affiliation.', NULL, NULL, '["VAULT", "EXCHANGE"]'::jsonb, '["open_bank", "currency_exchange"]'::jsonb, 145)
