values ('npc_ledger_warden_fortress_kaelen', 'Kael-Sigma', 'Ledger Warden — Fortress Kaelen', 'BANKER', 'GALACTIC_CUSTODIANS', 'Fortress Kaelen', 'FORTRESS_KAELEN', 'The Starforged Legion values order — and Custodian protocol is the only form of order they did not forge themselves. Kael-Sigma is tolerated, respected, and never challenged within these walls.', 'formal', 'Ledger Warden, Fortress Kaelen. Assets secured, rates standing. Make your request, warrior.', NULL, 'dlg_custodian_banker', 'CRD', NULL, 'Neutral Custodian vault and currency exchange. No faction affiliation.', NULL, NULL, '["VAULT", "EXCHANGE"]'::jsonb, '["open_bank", "currency_exchange"]'::jsonb, 146)
